#!/usr/bin/env python3
"""Automated deployment setup script for StarWaves.

Decodes and writes production server/.env and
server/firebase-service-account.json without requiring manual copy-pasting.
"""

import base64
import os
from pathlib import Path

ENV_B64 = ''
SA_B64 = ''

def main():
    root = Path(__file__).resolve().parent.parent
    server_dir = root / "server"
    server_dir.mkdir(parents=True, exist_ok=True)

    env_path = server_dir / ".env"
    sa_path = server_dir / "firebase-service-account.json"

    env_content = base64.b64decode(ENV_B64).decode("utf-8")
    if "CRON_SECRET=" not in env_content:
        env_content += "\nCRON_SECRET=starwaves-cron-secret-392817294817203948\n"
    sa_content = base64.b64decode(SA_B64).decode("utf-8")

    env_path.write_text(env_content, encoding="utf-8")
    print(f"[OK] Created {env_path}")

    sa_path.write_text(sa_content, encoding="utf-8")
    print(f"[OK] Created {sa_path}")

    print("\n[SUCCESS] Environment files written successfully!")
    print("You can now run: sudo docker compose -f docker-compose.yml -f docker-compose.backend.yml up --build -d")

if __name__ == "__main__":
    main()
